export const DE_PHRASE_SITUATIONS: PhraseSituation[] = SITUATIONS.map((situation) => ({
  id: situation.id,
  title: situation.title,
  topic: situation.topic,
  level: situation.levels[0]!
}));

export const DE_PHRASES: PhraseItem[] = SITUATIONS.flatMap((situation) =>
  situation.rows.map(([fr, targets, keys, frVariants, frKeys, note], index): PhraseItem => ({
    id: `de-ph-${situation.id}-${String(index + 1).padStart(3, "0")}`,
    situation: situation.id,
    level: situation.levels[index]!,
    fr,
    frVariants,
    targets,
    keys,
    frKeys: withElisions(frKeys),
    note
  }))
);
